// The lab's JS policies must compute exactly what the Python policies compute (ADR-022). The
// fixture is generated by `make export` from src/ctxcheck/policies; this replays every case.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { assemble, compact, tokensOf } from '../scene/policies.js';

const read = (p) => JSON.parse(readFileSync(new URL(p, import.meta.url)));
const lab = read('../../web/public/data/lab/constraint.json');
const cases = read('./fixtures/lab-parity.json');
const bySeed = Object.fromEntries(lab.seeds.map((h) => [h.seed, h]));

test('the fixture covers every policy across positions and budgets', () => {
  assert.ok(cases.length >= 300);
  assert.deepEqual([...new Set(cases.map((c) => c.policy))].sort(), ['head_tail', 'observation_mask', 'recency_truncate']);
  assert.ok(cases.some((c) => c.masked.length > 0), 'some cases mask tool outputs');
  assert.ok(cases.some((c) => c.kept.length < 20), 'some cases drop history');
});

test('every case: same messages kept, same outputs masked, same tokens after', () => {
  for (const c of cases) {
    const h = bySeed[c.seed];
    const win = assemble(h, c.position);
    const { out } = compact(h, win, c.policy, c.limit);
    const kept = out.filter((m) => !m.maskedFrom).map((m) => m.id);
    const masked = out.filter((m) => m.maskedFrom).map((m) => m.id).sort((a, b) => a - b);
    const label = `seed ${c.seed} pos ${c.position} limit ${c.limit} ${c.policy}`;
    assert.deepEqual(kept, c.kept.filter((i) => !c.masked.includes(i)), `kept: ${label}`);
    assert.deepEqual(masked, c.masked, `masked: ${label}`);
    assert.equal(h.tools_tokens + tokensOf(out), c.tokens_after, `tokens: ${label}`);
  }
});

test('the rule moves with the position and the window total does not change', () => {
  const h = bySeed[1];
  const totals = [0, 5, 17].map((p) => tokensOf(assemble(h, p)));
  assert.equal(new Set(totals).size, 1);
  assert.equal(assemble(h, 5).findIndex((m) => m.kind === 'rule') > assemble(h, 0).findIndex((m) => m.kind === 'rule'), true);
});
